import{_ as a,o as t,c as i,ae as o}from"./chunks/framework.Bs_1Tt6f.js";const u=JSON.parse('{"title":"Conventions & Terminology","description":"","frontmatter":{},"headers":[],"relativePath":"docs/conventions.md","filePath":"docs/conventions.md"}'),n={name:"docs/conventions.md"};function r(s,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="conventions-terminology" tabindex="-1">Conventions &amp; Terminology <a class="header-anchor" href="#conventions-terminology" aria-label="Permalink to &quot;Conventions &amp; Terminology&quot;">​</a></h1><p>To use the tool effectively, it is important to understand the terminology and data conventions it employs.</p><h2 id="patterns-transcriptions" tabindex="-1">Patterns (Transcriptions) <a class="header-anchor" href="#patterns-transcriptions" aria-label="Permalink to &quot;Patterns (Transcriptions)&quot;">​</a></h2><p>A <strong>Pattern</strong> refers to a sequence of abstract musical data from a transcription. Depending on your source data, this might be represented as a string of characters (e.g., Volpiano fonts) or structured data (e.g., MEI elements). The tool groups identical transcription sequences into unique patterns so you can analyze their graphical realizations.</p><h2 id="reference-ids-ref-ids" tabindex="-1">Reference IDs (Ref IDs) <a class="header-anchor" href="#reference-ids-ref-ids" aria-label="Permalink to &quot;Reference IDs (Ref IDs)&quot;">​</a></h2><p>A <strong>Reference ID</strong> (or Ref ID) is a stable identifier that you assign to a specific graphical shape or neume type.</p><ul><li>For example, you might decide that the standard <em>Clivis</em> in your repertoire is designated as Ref ID <code>10</code>.</li><li>This allows for a standardized numbering system across different manuscript sources. A <code>10</code> in Manuscript A is intended to be the same graphical concept as a <code>10</code> in Manuscript B.</li></ul><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><p>Often, a single Ref ID will have slight graphical variations. The tool supports <strong>Variants</strong> using alphabetical suffixes.</p><ul><li>For example, if Ref ID <code>10</code> has two distinct visual forms, you might classify them as <code>10a</code> and <code>10b</code>.</li><li>The tool can extract these suffixes automatically if they are included in your linked transcription data, or you can manually assign them during annotation.</li></ul><h2 id="global-vs-local-identifiers" tabindex="-1">Global vs. Local Identifiers <a class="header-anchor" href="#global-vs-local-identifiers" aria-label="Permalink to &quot;Global vs. Local Identifiers&quot;">​</a></h2><p>Because manuscript notation can be idiosyncratic, the tool supports a two-tiered identification system:</p><ol><li><strong>Global IDs</strong>: These are the default, project-wide identifiers assigned to a pattern. If an abstract transcription pattern almost always corresponds to Ref ID <code>12</code>, you set <code>12</code> as the Global ID.</li><li><strong>Local Overrides</strong>: If a specific manuscript uses a different graphical sign for that same musical pattern, you can assign a manuscript-specific Local ID that overrides the Global ID just for that source.</li></ol><h2 id="iiif-international-image-interoperability-framework" tabindex="-1">IIIF (International Image Interoperability Framework) <a class="header-anchor" href="#iiif-international-image-interoperability-framework" aria-label="Permalink to &quot;IIIF (International Image Interoperability Framework)&quot;">​</a></h2><p>The tool relies on <strong>IIIF Manifests</strong> to load manuscript images. IIIF is a standardized method used by major libraries (e.g., BnF, Gallica, specialized university archives) to serve high-resolution images over the web. You do not need to download gigabytes of images; simply provide the manifest URL.</p>',15)])])}const f=a(n,[["render",r]]);export{u as __pageData,f as default};
